static int load_linux_for_nonboot_cpu(u32 cpu, u32 aarch64, u32 load,
				      u32 *entry, boot_args_t *args)
{
	static const char *boot_cmd[] = {
		"boot_fit", "boot_android ${devtype} ${devnum}" };
	const char *user_cmd = env_get("amp_linux_cmd");
	ulong fdt;
	int i, ret;

	/*
	 * 默认走正常启动流程（boot_fit / boot_android），也就是从 boot 分区
	 * 里的镜像加载 Linux。bootm_states_unmask 挡掉最后的 OS_GO，于是
	 * 一切都准备好但不跳转，entry 从 images.ep 取。
	 *
	 * amp_linux_cmd 允许把这一步换成任意命令，典型用法是先用 mmc read
	 * 把 Image 和 DTB 读进内存，再 booti：
	 *
	 *   setenv amp_linux_cmd 'booti 0x40400000 - 0x4f000000'
	 *
	 * ★ 为什么需要这个
	 *
	 *   rkdeveloptool 那条 USB 通道写不到 32MB 以上（LBA >= 0x10000 的写
	 *   静默丢弃）。boot 分区从 LBA 51200 = 25MB 起，一个完整的 Android
	 *   镜像放不进剩下的 7MB。而裸 Image 可以放在任意够得着的 LBA 上，
	 *   用 mmc read 搬进内存 —— U-Boot 自己的 mmc 读写没有这个限制
	 *   （同一个 LBA 70000，rkdeveloptool 写不进去，mmc write 成功）。
	 *
	 *   booti 走的 do_booti() 同样经过 do_bootm_states()，所以
	 *   bootm_states_unmask 对它一样有效，不需要另写加载逻辑。
	 */

	env_set_hex("bootm_states_unmask", BOOTM_STATE_OS_GO);
	g_amp_loading_linux = true;
	if (user_cmd) {
		AMP_I("linux via amp_linux_cmd: %s\n", user_cmd);
		ret = run_command(user_cmd, 0);
	} else {
		for (i = 0; i < ARRAY_SIZE(boot_cmd); i++) {
			ret = run_command(boot_cmd[i], 0);
			if (!ret)
				break;
		}
	}
	g_amp_loading_linux = false;
