67	/* /sys/class/video4linux/<节点>/name 等于 want（或以它开头）的那个节点 */
68	
69	static int find_node(const char *want, int prefix, char *path, size_t len)
70	{
71	  struct dirent *de;
72	  DIR *d = opendir("/sys/class/video4linux");
73	  int found = 0;
74	
75	  if (d == NULL)
76	    return 0;
77	
78	  while (!found && (de = readdir(d)) != NULL) {
79	    char fn[300];
80	    char name[64] = "";
81	    FILE *f;
82	
83	    if (de->d_name[0] == '.')
84	      continue;
85	    snprintf(fn, sizeof(fn), "/sys/class/video4linux/%s/name", de->d_name);
86	    f = fopen(fn, "r");
87	    if (f == NULL)
88	      continue;
89	    if (fgets(name, sizeof(name), f) != NULL) {
90	      name[strcspn(name, "\n")] = 0;
91	      if (prefix ? strncmp(name, want, strlen(want)) == 0
92	                 : strcmp(name, want) == 0) {
93	        snprintf(path, len, "/dev/%s", de->d_name);
94	        found = 1;
95	      }
96	    }
97	    fclose(f);
98	  }
99	
100	  closedir(d);
101	  return found;
102	}
