104	/* 把最后一帧做成 PREVIEW_W 宽的灰度图发布到帧共享区 */
105	
106	static void show(const uint16_t *raw, unsigned w, unsigned h, unsigned bpl)
107	{
108	  unsigned ow = PREVIEW_W;
109	  unsigned oh = (unsigned)((uint64_t)h * ow / w) & ~1u;
110	  uint32_t hist[1024] = { 0 };
111	  unsigned stride16 = bpl / 2;
112	  unsigned x, y, p99 = 0, total = 0, acc = 0;
113	  struct k7f_hdr_s *hd;
114	  uint32_t *px;
115	  uint32_t slot;
116	  uint8_t *base;
117	  int fd;
118	
119	  /* 99% 分位：在缩小后的采样点上统计 */
120	
121	  for (y = 0; y < oh; y++)
122	    for (x = 0; x < ow; x++) {
123	      unsigned sy = (y * h / oh) & ~1u, sx = (x * w / ow) & ~1u;
124	      const uint16_t *q = raw + sy * stride16 + sx;
125	      unsigned v = (q[0] + q[1] + q[stride16] + q[stride16 + 1]) / 4;
126	
127	      hist[v & 1023]++;
128	      total++;
129	    }
130	  for (p99 = 0; p99 < 1023 && acc < total * 99 / 100; p99++)
131	    acc += hist[p99];
132	  if (p99 < 16)
133	    p99 = 16;
134	
135	  fd = open(FRAME_DEV, O_RDWR);
136	  if (fd < 0) {
137	    printf("打不开 %s: %s\n", FRAME_DEV, strerror(errno));
138	    return;
139	  }
140	  base = mmap(NULL, FRAME_SHM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
141	  close(fd);
142	  if (base == MAP_FAILED) {
143	    printf("mmap %s 失败: %s\n", FRAME_DEV, strerror(errno));
144	    return;
145	  }
146	  printf("帧共享区: %p + %u\n", (void *)base, FRAME_SHM_SIZE);
147	
148	  hd = (struct k7f_hdr_s *)base;
149	  if (hd->magic != K7F_MAGIC || hd->version != K7F_VERSION) {
150	    memset(hd, 0, K7F_HDR_SIZE);
151	    hd->slot_size = ((FRAME_SHM_SIZE - K7F_HDR_SIZE) / K7F_SLOTS) &
152	                    ~(K7F_HDR_SIZE - 1);
153	    hd->version = K7F_VERSION;
154	    __asm__ volatile("dsb sy" ::: "memory");
155	    hd->magic = K7F_MAGIC;
156	  }
157	
158	  slot = hd->seq == 0 ? 0 : (hd->slot + 1) % K7F_SLOTS;
159	  px = (uint32_t *)(base + k7f_slot_offset(hd, slot));
160	  for (y = 0; y < oh; y++)
161	    for (x = 0; x < ow; x++) {
162	      unsigned sy = (y * h / oh) & ~1u, sx = (x * w / ow) & ~1u;
163	      const uint16_t *q = raw + sy * stride16 + sx;
164	      unsigned v = (q[0] + q[1] + q[stride16] + q[stride16 + 1]) / 4;
165	      unsigned g = v >= p99 ? 255 : v * 255 / p99;
166	
167	      px[y * ow + x] = 0xff000000u | (g << 16) | (g << 8) | g;
168	    }
169	
170	  __asm__ volatile("dsb sy" ::: "memory");
171	  hd->slot = slot;
172	  hd->width = ow;
173	  hd->height = oh;
174	  hd->stride = ow * 4;
175	  hd->format = K7F_FMT_XRGB8888;
176	  hd->bytes = ow * 4 * oh;
177	  hd->source = K7F_SRC_CAMERA;
178	  hd->seed = 0;
179	  __asm__ volatile("dsb sy" ::: "memory");
180	  hd->seq++;
181	  __asm__ volatile("dsb sy" ::: "memory");
182	
183	  printf("预览已发布：seq=%u 槽=%u %ux%u（RAW 99%% 分位 %u 拉到 255）\n",
184	         hd->seq, slot, ow, oh, p99);
185	  munmap(base, FRAME_SHM_SIZE);
186	}
