188	/* 写一个子设备控件，并把驱动实际接受的值和范围读回来报告 */
189	
190	static void set_ctrl(int sfd, unsigned id, const char *name, int val)
191	{
192	  struct v4l2_queryctrl qc = { .id = id };
193	  struct v4l2_control c = { .id = id, .value = val };
194	
195	  if (ioctl(sfd, VIDIOC_QUERYCTRL, &qc) < 0) {
196	    printf("%s: 传感器没有这个控件（%s）\n", name, strerror(errno));
197	    return;
198	  }
199	  if (ioctl(sfd, VIDIOC_S_CTRL, &c) < 0)
200	    printf("%s=%d 失败: %s\n", name, val, strerror(errno));
201	  c.value = 0;
202	  ioctl(sfd, VIDIOC_G_CTRL, &c);
203	  printf("%s = %d（范围 %d~%d）\n", name, c.value, qc.minimum, qc.maximum);
204	}
