206	static int cap_main(int frames, int want_show, int exposure, int gain)
207	{
208	  struct v4l2_subdev_format sf = { .which = V4L2_SUBDEV_FORMAT_ACTIVE };
209	  struct v4l2_requestbuffers rb = { 0 };
210	  struct v4l2_format fmt = { 0 };
211	  struct buf_s bufs[NBUF] = { 0 };
212	  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE_MPLANE;
213	  char vpath[300], spath[300];
214	  int fd = -1, sfd, mode = CSI_LVDS_MEM_WORD_LOW_ALIGN;
215	  int got = 0, streaming = 0, ret = 1, i;
216	  long t_start, deadline, t_prev = 0, t_first = 0;
217	  unsigned w, h, bpl;
218	
219	  if (!find_node(CIF_NAME, 0, vpath, sizeof(vpath))) {
220	    printf("找不到 %s（摄像头模块没装上？看 dmesg 里的 k7 camera）\n", CIF_NAME);
221	    return 1;
222	  }
223	  if (!find_node(SENSOR_PREFIX, 1, spath, sizeof(spath))) {
224	    printf("找不到 IMX415 的子设备节点\n");
225	    return 1;
226	  }
227	
228	  /* 传感器当前输出多大，CIF 就按多大收 */
229	
230	  sfd = open(spath, O_RDWR);
231	  if (sfd < 0 || ioctl(sfd, VIDIOC_SUBDEV_G_FMT, &sf) < 0) {
232	    printf("读 %s 格式失败: %s\n", spath, strerror(errno));
233	    if (sfd >= 0)
234	      close(sfd);
235	    return 1;
236	  }
237	  printf("传感器 %s: %ux%u code=0x%04x\n", spath, sf.format.width,
238	         sf.format.height, sf.format.code);
239	  if (exposure > 0)
240	    set_ctrl(sfd, V4L2_CID_EXPOSURE, "曝光", exposure);
241	  if (gain >= 0)
242	    set_ctrl(sfd, V4L2_CID_ANALOGUE_GAIN, "模拟增益", gain);
243	
244	  close(sfd);
245	
246	  fd = open(vpath, O_RDWR | O_NONBLOCK);
247	  if (fd < 0) {
248	    printf("打不开 %s: %s\n", vpath, strerror(errno));
249	    return 1;
250	  }
251	
252	  if (ioctl(fd, RKCIF_CMD_SET_CSI_MEMORY_MODE, &mode) < 0)
253	    printf("设 16 位低对齐失败（%s），按驱动给的 bytesperline 走\n",
254	           strerror(errno));
255	
256	  fmt.type = type;
257	  fmt.fmt.pix_mp.width = sf.format.width;
258	  fmt.fmt.pix_mp.height = sf.format.height;
259	  fmt.fmt.pix_mp.pixelformat = V4L2_PIX_FMT_SGBRG10;
260	  fmt.fmt.pix_mp.num_planes = 1;
261	  if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
262	    printf("S_FMT 失败: %s\n", strerror(errno));
263	    goto out;
264	  }
265	  w = fmt.fmt.pix_mp.width;
266	  h = fmt.fmt.pix_mp.height;
267	  bpl = fmt.fmt.pix_mp.plane_fmt[0].bytesperline;
268	  printf("CIF %s: %ux%u fourcc=%.4s bytesperline=%u sizeimage=%u\n", vpath,
269	         w, h, (char *)&fmt.fmt.pix_mp.pixelformat, bpl,
270	         fmt.fmt.pix_mp.plane_fmt[0].sizeimage);
271	
272	  /* ★ 实际尺寸以 bytesperline / sizeimage 为准，不信 width / height。
273	   *
274	   *   IMX415 报 3864x2192，CIF 回的 width/height 也照抄这个数，但它按
275	   *   3840x2160 裁（bytesperline 7680、sizeimage 16588800）。按 2192 行
276	   *   去读，最后 32 行就越过缓冲区尾 —— 第一次跑就是这么 SIGBUS 的，
277	   *   出错地址正好是缓冲起点 + 16588800。
278	   */
279	  if (bpl / 2 < w)
280	    w = bpl / 2;
281	  if (fmt.fmt.pix_mp.plane_fmt[0].sizeimage / bpl < h)
282	    h = fmt.fmt.pix_mp.plane_fmt[0].sizeimage / bpl;
283	  printf("按 %ux%u（16 位/像素）解释\n", w, h);
284	
285	  rb.count = NBUF;
286	  rb.type = type;
287	  rb.memory = V4L2_MEMORY_MMAP;
288	  if (ioctl(fd, VIDIOC_REQBUFS, &rb) < 0 || rb.count < 2) {
289	    printf("REQBUFS 失败: %s（给了 %u 个）\n", strerror(errno), rb.count);
290	    goto out;
291	  }
292	
293	  for (i = 0; i < (int)rb.count; i++) {
294	    struct v4l2_plane pl[VIDEO_MAX_PLANES] = { 0 };
295	    struct v4l2_buffer b = { .type = type, .memory = V4L2_MEMORY_MMAP,
296	                             .index = i, .m.planes = pl, .length = 1 };
297	
298	    if (ioctl(fd, VIDIOC_QUERYBUF, &b) < 0) {
299	      printf("QUERYBUF %d 失败: %s\n", i, strerror(errno));
300	      goto out;
301	    }
302	    bufs[i].len = pl[0].length;
303	    bufs[i].p = mmap(NULL, pl[0].length, PROT_READ | PROT_WRITE, MAP_SHARED,
304	                     fd, pl[0].m.mem_offset);
305	    if (bufs[i].p == MAP_FAILED) {
306	      bufs[i].p = NULL;
307	      printf("mmap 缓冲 %d 失败: %s\n", i, strerror(errno));
308	      goto out;
309	    }
310	    printf("缓冲 %d: %p + %zu\n", i, bufs[i].p, bufs[i].len);
311	    if (ioctl(fd, VIDIOC_QBUF, &b) < 0) {
312	      printf("QBUF %d 失败: %s\n", i, strerror(errno));
313	      goto out;
314	    }
315	  }
316	
317	  if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
318	    printf("STREAMON 失败: %s\n", strerror(errno));
319	    goto out;
320	  }
321	  streaming = 1;
322	
323	  /* 总期限：每帧按 200ms 算（5fps 都够），再加 3 秒起流 */
324	
325	  t_start = now_ms();
326	  deadline = t_start + 3000 + frames * 200L;
327	
328	  while (got < frames) {
329	    struct v4l2_plane pl[VIDEO_MAX_PLANES] = { 0 };
330	    struct v4l2_buffer b = { .type = type, .memory = V4L2_MEMORY_MMAP,
331	                             .m.planes = pl, .length = 1 };
332	    struct pollfd pfd = { .fd = fd, .events = POLLIN };
333	    long left = deadline - now_ms();
334	    uint64_t sum[4] = { 0 };
335	    unsigned n4 = 0, x, y, stride16 = bpl / 2;
336	    const uint16_t *raw;
337	    long t;
338	    int pr;
339	
340	    if (left <= 0) {
341	      printf("到总期限了，拿到 %d/%d 帧\n", got, frames);
342	      break;
343	    }
344	    pr = poll(&pfd, 1, left < POLL_MS ? (int)left : POLL_MS);
345	    if (pr == 0) {
346	      printf("%d ms 内没有新帧（已拿到 %d 帧）\n", POLL_MS, got);
347	      break;
348	    }
349	    if (pr < 0 || ioctl(fd, VIDIOC_DQBUF, &b) < 0) {
350	      printf("等帧/DQBUF 失败: %s\n", strerror(errno));
351	      break;
352	    }
353	
354	    t = now_ms();
355	    raw = bufs[b.index].p;
356	
357	    /* 四个 Bayer 相位分开求均值：GBRG 下 [0]=G [1]=B [2]=R [3]=G */
358	
359	    for (y = 0; y + 1 < h; y += 16)
360	      for (x = 0; x + 1 < w; x += 16) {
361	        const uint16_t *q = raw + y * stride16 + x;
362	
363	        sum[0] += q[0];
364	        sum[1] += q[1];
365	        sum[2] += q[stride16];
366	        sum[3] += q[stride16 + 1];
367	        n4++;
368	      }
369	
370	    got++;
371	    if (got == 1)
372	      t_first = t;
373	    printf("帧 %d: seq=%u 字节=%u 间隔=%ld ms  均值 G=%u B=%u R=%u G=%u "
374	           "(0~1023)%s\n", got, b.sequence, pl[0].bytesused,
375	           t_prev ? t - t_prev : 0, (unsigned)(sum[0] / n4),
376	           (unsigned)(sum[1] / n4), (unsigned)(sum[2] / n4),
377	           (unsigned)(sum[3] / n4), b.flags & V4L2_BUF_FLAG_ERROR ? " ERROR" : "");
378	    fflush(stdout);
379	    t_prev = t;
380	
381	    if (got == frames && want_show)
382	      show(raw, w, h, bpl);
383	
384	    if (ioctl(fd, VIDIOC_QBUF, &b) < 0) {
385	      printf("回填 QBUF 失败: %s\n", strerror(errno));
386	      break;
387	    }
388	  }
389	
390	  if (got > 1)
391	    printf("共 %d 帧，平均 %.1f fps（首帧在起流后 %ld ms）\n", got,
392	           (got - 1) * 1000.0 / (t_prev - t_first > 0 ? t_prev - t_first : 1),
393	           t_first - t_start);
394	  ret = got == frames ? 0 : 1;
395	
396	out:
397	  if (streaming)
398	    ioctl(fd, VIDIOC_STREAMOFF, &type);
399	  for (i = 0; i < NBUF; i++)
400	    if (bufs[i].p != NULL)
401	      munmap(bufs[i].p, bufs[i].len);
402	  if (fd >= 0)
403	    close(fd);
404	  return ret;
405	}
