407	/* SIGBUS/SIGSEGV 时报出出错的地址再退出：取图缓冲和帧共享区都是 mmap
408	 * 进来的，哪一块出的问题，看地址落在哪儿就知道（下面打印了各块的范围）。
409	 */
410	
411	static void on_fault(int sig, siginfo_t *si, void *ctx)
412	{
413	  char msg[96];
414	  int n;
415	
416	  (void)ctx;
417	  n = snprintf(msg, sizeof(msg), "\n★ 收到信号 %d，地址 %p，si_code %d\n",
418	               sig, si->si_addr, si->si_code);
419	  write(1, msg, n);
420	  _exit(128 + sig);
421	}
422	
423	int main(int argc, char **argv)
424	{
425	  struct sigaction sa = { .sa_sigaction = on_fault, .sa_flags = SA_SIGINFO };
426	  int frames = argc > 2 ? atoi(argv[2]) : 10;
427	  int want_show = argc > 3 && strcmp(argv[3], "show") == 0;
428	  int exposure = argc > 4 ? atoi(argv[4]) : 0;
429	  int gain = argc > 5 ? atoi(argv[5]) : -1;
430	
431	  if (argc < 2 || strcmp(argv[1], "cap") != 0 || frames < 1 ||
432	      frames > MAX_FRAMES) {
433	    printf("用法: k7cam cap [帧数 1~%d] [show|-] [曝光行数] [模拟增益]\n",
434	           MAX_FRAMES);
435	    return 2;
436	  }
437	
438	  /* 输出经 rpmsg 管道回到 openvela；不关缓冲的话，进程一出事最后几行就丢了 */
